1	// Cold Email Engine — IMAP reply poller (Overhaul Phase 1).
2	//
3	// Registered on the worker loop (worker/index.ts). For each Inbox that has REAL
4	// IMAP credentials it connects, fetches messages newer than the stored UID
5	// bookmark, and for every reply from a known contact it:
6	//   1. upserts a Conversation + appends an INBOUND Message (idempotent on UID),
7	//   2. moves the contact to stage REPLIED,
8	//   3. HALTS the contact's remaining queued sends (mail-side reply detection),
9	//   4. writes a REPLY EmailEvent + DeliverabilityEvent for the analytics spine,
10	//   5. classifies the reply (rules first, then Claude if a key exists) and sets the
11	//      conversation status + contact stage; an UNSUBSCRIBE writes a GLOBAL Suppression,
12	//   6. fires reply / interested / unsubscribe webhooks.
13	//
14	// SAFETY: this is send-INDEPENDENT and creds-gated. An inbox with a blank imapHost
15	// is never touched — no creds, no connection. It reads mail; it never sends here.
16	// Degrades gracefully with no ANTHROPIC_API_KEY (the reply stays classified only by
17	// rules, else left OPEN). Never throws to the caller — a bad mailbox is logged and
18	// skipped so one inbox can't stall the sweep.
19	
20	import { ImapFlow } from "imapflow";
21	import { simpleParser, type ParsedMail } from "mailparser";
22	import { db } from "../lib/db";
23	import { decryptSecret } from "../lib/crypto-box";
24	import { normalizeEmail } from "../lib/coldemail/compliance";
25	import { matchColdSendId, buildSentIndex } from "../lib/coldemail/inbox-match";
26	import { normalizeMessageId } from "../lib/coldemail/threading";
27	import {
28	  classifyReply,
29	  isUnsubscribeRequest,
30	  classToConversationStatus,
31	  classToContactStage,
32	  classNeedsSuppression,
33	  type ReplyClass,
34	} from "../lib/coldemail/classify";
35	import { fireWebhooks } from "../lib/coldemail/webhooks";
36	import { applyContactHygiene, recordFeedback } from "../lib/coldemail/feedback";
37	import { logEvent } from "../lib/log";
38	
39	type PollInbox = {
40	  id: string;
41	  email: string;
42	  imapHost: string;
43	  imapPort: number;
44	  imapUser: string;
45	  imapPassEnc: string;
46	  imapTls: boolean;
47	  lastImapUid: number;
48	};
49	
50	/** Cap on messages examined per inbox per sweep — keeps a first poll bounded. */
51	const MAX_MESSAGES_PER_INBOX = 200;
52	
53	/** The sweep entrypoint. Polls every credentialed inbox; isolates failures. */
54	export async function coldEmailInboxPoll(): Promise<void> {
55	  let inboxes: PollInbox[];
56	  try {
57	    inboxes = await db.inbox.findMany({
58	      where: { imapHost: { not: "" }, imapUser: { not: "" } },
59	      select: {
60	        id: true,
61	        email: true,
62	        imapHost: true,
63	        imapPort: true,
64	        imapUser: true,
65	        imapPassEnc: true,
66	        imapTls: true,
67	        lastImapUid: true,
68	      },
69	    });
70	  } catch {
71	    return; // tables not migrated on this env — behave like a no-op
72	  }
73	  if (inboxes.length === 0) return; // no credentialed inboxes — nothing connects
74	
75	  for (const ib of inboxes) {
76	    try {
77	      await pollOneInbox(ib);
78	    } catch (err) {
79	      await logEvent("error", "coldemail.inbox.poll", { inboxId: ib.id, message: String((err as Error)?.message ?? err) });
80	    }
81	  }
82	}
83	
84	async function pollOneInbox(ib: PollInbox): Promise<void> {
85	  const pass = decryptSecret(ib.imapPassEnc);
86	  if (!pass) return; // password absent or undecryptable — cannot connect, skip quietly
87	
88	  // imapHost is the mailbox's real internal IP (mail.nxeon.cloud's public DNS points
89	  // at the platform host, not Mailcow — connecting by hostname silently reaches the
90	  // wrong server). The cert is issued for the hostname, so TLS needs an explicit
91	  // servername override or certificate hostname verification fails against the IP.
92	  const client = new ImapFlow({
93	    host: ib.imapHost,
94	    port: ib.imapPort || 993,
95	    secure: ib.imapTls,
96	    auth: { user: ib.imapUser, pass },
97	    tls: { servername: "mail.nxeon.cloud" },
98	    logger: false,
99	    emitLogs: false,
100	  });
101	
102	  let maxUid = ib.lastImapUid;
103	  await client.connect();
104	  try {
105	    const lock = await client.getMailboxLock("INBOX");
106	    try {
107	      const startUid = ib.lastImapUid + 1;
108	      let seen = 0;
109	      // UID-based fetch: `${startUid}:*` returns everything above the bookmark. The
110	      // `X:*` IMAP quirk can echo the latest message even when none is newer, so we
111	      // re-check `uid > lastImapUid` per row.
112	      for await (const msg of client.fetch(`${startUid}:*`, { uid: true, source: true, envelope: true }, { uid: true })) {
113	        if (seen >= MAX_MESSAGES_PER_INBOX) break;
114	        seen++;
115	        const uid = msg.uid;
116	        if (!uid || uid <= ib.lastImapUid) continue;
117	        if (uid > maxUid) maxUid = uid;
118	        if (!msg.source) continue;
119	        try {
120	          await ingestMessage(ib, uid, await simpleParser(msg.source as Buffer));
121	        } catch (err) {
122	          await logEvent("error", "coldemail.inbox.ingest", { inboxId: ib.id, uid, message: String((err as Error)?.message ?? err) });
123	        }
124	      }
125	    } finally {
126	      lock.release();
127	    }
128	  } finally {
129	    await client.logout().catch(() => null);
130	  }
131	
132	  // Advance the bookmark + stamp the poll even when nothing matched, so we never
133	  // re-scan the same UIDs next sweep.
134	  await db.inbox
135	    .update({ where: { id: ib.id }, data: { lastImapUid: Math.max(maxUid, ib.lastImapUid), lastPolledAt: new Date() } })
136	    .catch(() => null);
137	}
138	
139	/**
140	 * Does this inbound message look like a bounce/NDR rather than a human reply? A
141	 * real bounce comes from mailer-daemon/postmaster (never a contact), or carries a
142	 * standard RFC 3464 delivery-status part, or has bounce-shaped subject wording.
143	 */
144	function looksLikeBounce(parsed: ParsedMail, fromAddr: string): boolean {
145	  if (/^(mailer-daemon|postmaster)@/i.test(fromAddr)) return true;
146	  if (parsed.attachments?.some((a) => /^message\/delivery-status$/i.test(a.contentType))) return true;
147	  const subject = (parsed.subject ?? "").toLowerCase();
148	  return /undeliverable|delivery status notification|delivery has failed|returned to sender|failure notice|mail delivery (?:failed|subsystem)/i.test(
149	    subject,
150	  );
151	}
152	
153	/**
154	 * Recover the bounced address + severity from a standard DSN (RFC 3464): the
155	 * message/delivery-status part carries `Final-Recipient: rfc822;<addr>` and
156	 * `Status: 5.x.x` (permanent) or `4.x.x` (transient). Falls back to scanning the
157	 * whole body for the same fields when a sending MTA didn't attach a proper part.
158	 */
159	function parseDsnBounce(parsed: ParsedMail): { email: string; hard: boolean } | null {
160	  const dsnPart = parsed.attachments?.find((a) => /^message\/delivery-status$/i.test(a.contentType));
161	  const text = dsnPart ? dsnPart.content.toString("utf8") : (parsed.text ?? "");
162	
163	  const recipMatch = text.match(/Final-Recipient:\s*rfc822;\s*<?([^\s>]+)>?/i);
164	  const email = normalizeEmail(recipMatch?.[1]);
165	  if (!email || !email.includes("@")) return null;
166	
167	  const statusMatch = text.match(/Status:\s*(\d)\.\d+\.\d+/i);
168	  const hard = statusMatch
169	    ? statusMatch[1] === "5"
170	    : !/\btry(?:ing)? again\b|\btemporar(?:y|ily)\b|\bmailbox (?:full|over quota)\b/i.test(text);
171	  return { email, hard };
172	}
173	
174	/** Turn one parsed inbound message into a Conversation + Message (+ side effects). */
175	async function ingestMessage(ib: PollInbox, uid: number, parsed: ParsedMail): Promise<void> {
176	  const fromAddr = normalizeEmail(parsed.from?.value?.[0]?.address ?? "");
177	  if (!fromAddr || !fromAddr.includes("@")) return;
178	  // Ignore our own sent copies that may live in this mailbox.
179	  if (fromAddr === normalizeEmail(ib.email)) return;
180	
181	  // A bounce/NDR is never a contact reply — it comes from mailer-daemon, not the
182	  // recipient — so it must be routed to the hygiene pipeline here, before the
183	  // "known contact" gate below, or it is silently dropped and never suppressed.
184	  if (looksLikeBounce(parsed, fromAddr)) {
185	    const bounce = parseDsnBounce(parsed);
186	    if (bounce) {
187	      await recordFeedback(bounce.email, bounce.hard ? "HARD_BOUNCE" : "SOFT_BOUNCE", {
188	        note: (parsed.subject ?? "").slice(0, 300),
189	      }).catch((err) => logEvent("error", "coldemail.inbox.bounce", { inboxId: ib.id, uid, message: String(err) }));
190	    } else {
191	      await logEvent("warn", "coldemail.inbox.bounce_unparsed", { inboxId: ib.id, uid, subject: parsed.subject ?? "" });
192	    }
193	    return;
194	  }
195	
196	  // Only capture replies from a KNOWN contact (a reply to our outreach).
197	  const contact = await db.contact.findUnique({ where: { email: fromAddr }, select: { id: true, fullName: true, stage: true } });
198	  if (!contact) return;
199	
200	  const messageId = normalizeMessageId(parsed.messageId) || `<imap-${ib.id}-${uid}@nxeon>`;
201	  // Idempotency: if we already stored this Message-ID in this inbox's thread, stop.
202	  const dupe = await db.message.findFirst({
203	    where: { messageId, conversation: { inboxId: ib.id } },
204	    select: { id: true },
205	  });
206	  if (dupe) return;
207	
208	  const subject = (parsed.subject ?? "").slice(0, 300);
209	  const bodyText = (parsed.text ?? "").trim();
210	  const bodyHtml = typeof parsed.html === "string" ? parsed.html : "";
211	  const inReplyTo = normalizeMessageId(parsed.inReplyTo);
212	  const references = Array.isArray(parsed.references)
213	    ? parsed.references.map(normalizeMessageId).join(" ")
214	    : normalizeMessageId(parsed.references as string | undefined);
215	  const receivedAt = parsed.date ?? new Date();
216	
217	  // ---- Match the originating send (threading first, recipient fallback) ----
218	  const contactSends = await db.coldSend.findMany({
219	    where: { contactId: contact.id, inboxId: ib.id },
220	    orderBy: { createdAt: "desc" },
221	    select: { id: true, messageId: true, campaignId: true },
222	  });
223	  const matchedSendId =
224	    matchColdSendId(inReplyTo, references, buildSentIndex(contactSends)) ?? (contactSends[0]?.id ?? null);
225	  const matchedCampaignId =
226	    contactSends.find((s) => s.id === matchedSendId)?.campaignId ?? contactSends[0]?.campaignId ?? null;
227	
228	  // ---- Upsert the conversation ----
229	  const convo = await db.conversation.upsert({
230	    where: { inboxId_contactId: { inboxId: ib.id, contactId: contact.id } },
231	    create: {
232	      inboxId: ib.id,
233	      contactId: contact.id,
234	      campaignId: matchedCampaignId,
235	      subject,
236	      status: "REPLIED",
237	      lastMessageAt: receivedAt,
238	      unread: true,
239	    },
240	    update: {
241	      lastMessageAt: receivedAt,
242	      unread: true,
243	      // Fill campaign if we now know it and didn't before.
244	      ...(matchedCampaignId ? { campaignId: matchedCampaignId } : {}),
245	    },
246	    select: { id: true, status: true },
247	  });
248	
249	  // ---- Append the inbound message ----
250	  await db.message.create({
251	    data: {
252	      conversationId: convo.id,
253	      direction: "INBOUND",
254	      fromAddr,
255	      toAddr: normalizeEmail(ib.email),
256	      subject,
257	      bodyText: bodyText.slice(0, 100_000),
258	      bodyHtml: bodyHtml.slice(0, 200_000),
259	      messageId,
260	      inReplyTo,
261	      references,
262	      coldSendId: matchedSendId,
263	      receivedAt,
264	    },
265	  });
266	
267	  // ---- Advance the contact to REPLIED (never downgrade a warmer stage) ----
268	  await db.contact.updateMany({
269	    where: { id: contact.id, stage: { in: ["NEW", "CONTACTED"] } },
270	    data: { stage: "REPLIED" },
271	  });
272	  // Stamp the first-reply time (engagement signal for the lead DB).
273	  await db.contact.updateMany({ where: { id: contact.id, repliedAt: null }, data: { repliedAt: receivedAt } }).catch(() => null);
274	
275	  // ---- HALT the contact's remaining queued sends (mail-side reply detection) ----
276	  await db.coldSend
277	    .updateMany({
278	      where: { contactId: contact.id, status: "QUEUED" },
279	      data: { status: "CANCELLED", error: "Halted: contact replied" },
280	    })
281	    .catch(() => null);
282	
283	  // ---- Analytics spine: REPLY event(s) ----
284	  if (matchedSendId) {
285	    await db.emailEvent.create({ data: { sendId: matchedSendId, type: "REPLY" } }).catch(() => null);
286	  }
287	  await db.deliverabilityEvent
288	    .create({
289	      data: {
290	        type: "REPLY",
291	        inboxId: ib.id,
292	        campaignId: matchedCampaignId,
293	        contactId: contact.id,
294	        sendId: matchedSendId,
295	        provider: "imap",
296	      },
297	    })
298	    .catch(() => null);
299	
300	  // ---- Classify (rules always; Claude only if a key exists) ----
301	  const cls = await classifyReply(subject, bodyText, {});
302	  const unsub = cls === "UNSUBSCRIBE" || isUnsubscribeRequest(`${subject}\n${bodyText}`);
303	
304	  const finalStatus = cls ? classToConversationStatus(cls) : convo.status === "OPEN" ? "REPLIED" : "REPLIED";
305	  await db.conversation.update({
306	    where: { id: convo.id },
307	    data: { status: finalStatus, category: cls ?? "" },
308	  });
309	
310	  // Stage advancement from the classification (don't clobber WON/MEETING_BOOKED).
311	  const stageAdvance = cls ? classToContactStage(cls) : null;
312	  if (stageAdvance) {
313	    await db.contact
314	      .updateMany({ where: { id: contact.id, stage: { notIn: ["WON", "MEETING_BOOKED"] } }, data: { stage: stageAdvance } })
315	      .catch(() => null);
316	  }
317	
318	  // ---- Unsubscribe → contact UNSUBSCRIBED (dead) + GLOBAL suppression (idempotent) ----
319	  if (unsub) {
320	    // Run the lead-DB hygiene pipeline: sets emailStatus=UNSUBSCRIBED + deadAt so
321	    // this contact is excluded from every future campaign, then suppress globally.
322	    await applyContactHygiene(contact.id, "UNSUBSCRIBE", "Unsubscribe reply").catch(() => null);
323	    const existing = await db.suppression.findFirst({ where: { email: fromAddr, scope: "GLOBAL" }, select: { id: true } });
324	    if (!existing) {
325	      await db.suppression.create({ data: { email: fromAddr, scope: "GLOBAL", reason: "UNSUBSCRIBE" } }).catch(() => null);
326	    }
327	    await db.emailEvent.create({ data: { sendId: matchedSendId ?? "", type: "UNSUBSCRIBE" } }).catch(() => null);
328	  }
329	
330	  // ---- Webhooks ----
331	  await fireWebhookForReply(convo.id, fromAddr, contact.fullName, matchedCampaignId, ib.email, finalStatus, bodyText, cls, unsub);
332	}
333	
334	/** Fan out the reply / interested / unsubscribe webhook events. Best-effort. */
335	async function fireWebhookForReply(
336	  conversationId: string,
337	  contactEmail: string,
338	  contactName: string | null | undefined,
339	  campaignId: string | null,
340	  inboxEmail: string,
341	  status: string,
342	  body: string,
343	  cls: ReplyClass | null,
344	  unsub: boolean,
345	): Promise<void> {
346	  const base = {
347	    conversationId,
348	    contactEmail,
349	    contactName: contactName ?? undefined,
350	    campaignId,
351	    inboxEmail,
352	    status,
353	    snippet: body.replace(/\s+/g, " ").trim().slice(0, 280),
354	    occurredAt: new Date().toISOString(),
355	  };
356	  await fireWebhooks("reply", base);
357	  if (cls === "INTERESTED") await fireWebhooks("interested", base);
358	  if (unsub) await fireWebhooks("unsubscribe", base);
359	}
