1	// Cold Email Engine — send-queue processor (Phase 2).
2	//
3	// Registered on the worker loop (worker/index.ts) and gated HARD behind the
4	// `cold_email_sending_enabled` master kill-switch: while that Setting is false
5	// this sweep returns immediately and NOTHING is scheduled, rendered, or sent.
6	//
7	// For each SENDING campaign it:
8	//   1. Re-checks brand send-eligibility (compliance + reputation isolation +
9	//      circuit-breaker pause). A blocked brand is skipped, never sent.
10	//   2. Expands the list → contacts → schedules a ColdSend per SequenceStep,
11	//      honouring delayDays (idempotent via the unique (campaign, contact, step)).
12	//   3. Sends due rows, enforcing at SEND TIME: suppression re-check, per-inbox
13	//      daily cap with the warmup ramp, and the send window — writing ColdSend
14	//      status (SENT/FAILED/SUPPRESSED) + an EmailEvent, throttled with jitter.
15	//
16	// Every count comes from the DB; the only external call is the SMTP send itself,
17	// which is unreachable in tests because the kill-switch keeps this inert.
18	
19	import { db } from "../lib/db";
20	import { getSetting, getSettingBool } from "../lib/settings";
21	import {
22	  isSuppressed,
23	  evaluateSendEligibility,
24	  protectedDomainSet,
25	  effectiveDailyCap,
26	  openTrackingToken,
27	  type SuppressionLike,
28	} from "../lib/coldemail/compliance";
29	import { buildMessage, getTransport, NxeonSmtpTransport, type SendIdentity, type MailTransport } from "../lib/coldemail/sender";
30	import { inboxAllowedVolume } from "../lib/coldemail/warmup";
31	import { selectNextInbox, type RotationInbox } from "../lib/coldemail/rotation";
32	import { isMailableStatus } from "../lib/coldemail/leaddb";
33	import { logEvent } from "../lib/log";
34	import { decryptSecret } from "../lib/crypto-box";
35	
36	/**
37	 * A brand's rotation pool for this sweep: the ACTIVE inboxes on its authenticated
38	 * domains, each with the send identity + today's warmup-clamped allowance and the
39	 * live rotation candidate the selector mutates as sends go out.
40	 */
41	type PoolInbox = {
42	  candidate: RotationInbox;
43	  identity: SendIdentity;
44	  sendingDomainId: string;
45	  // The inbox's OWN SMTP creds — sends must go out through the isolated relay
46	  // this specific inbox is configured for, never the platform's shared
47	  // transactional SMTP (see the launch-blocking bug this fixes: the send loop
48	  // used to build ONE shared "nxeon-smtp" transport for the whole sweep and
49	  // reuse it regardless of which inbox was chosen, so a message claiming
50	  // `From: hello@trynxeon.com` actually went out authenticated as the
51	  // platform's own noreply@nxeon.cloud over the transactional relay —
52	  // defeating the entire point of a reputation-isolated sending domain).
53	  smtp: { host: string; port: number; user: string; passEnc: string; tls: boolean };
54	};
55	
56	/**
57	 * Load a brand's rotation pool. Returns [] when the brand has no inboxes — the
58	 * worker then falls back to the Phase 2 brand-level cap path unchanged. Only
59	 * inboxes on a domain with SPF+DKIM+DMARC all verified are authenticated (authGreen).
60	 */
61	async function loadBrandRotationPool(brandId: string, brand: SendIdentity, now: Date): Promise<PoolInbox[]> {
62	  let inboxes;
63	  try {
64	    inboxes = await db.inbox.findMany({
65	      // Only ACTIVE inboxes on a domain that is not paused/burned. A domain-level
66	      // auto-pause therefore takes every one of its inboxes out of rotation.
67	      // smtpHost not empty: the documented "blank host = never connects" guard
68	      // (see Inbox.smtpHost's schema comment) — an ACTIVE inbox with no creds
69	      // configured must never be picked for rotation.
70	      where: { status: "ACTIVE", smtpHost: { not: "" }, sendingDomain: { brandId, status: { notIn: ["PAUSED", "BURNED"] } } },
71	      include: { sendingDomain: true },
72	    });
73	  } catch {
74	    return []; // tables not migrated on this env — behave like Phase 2
75	  }
76	  if (inboxes.length === 0) return [];
77	
78	  const dayStart = startOfUtcDay(now);
79	  const pool: PoolInbox[] = [];
80	  for (const ib of inboxes) {
81	    const d = ib.sendingDomain;
82	    const authGreen = !!(d?.spfVerified && d?.dkimVerified && d?.dmarcVerified);
83	    const allowedToday = inboxAllowedVolume({
84	      warmupStartedAt: ib.warmupStartedAt,
85	      plan: { startCap: ib.startCap, targetCap: ib.targetCap, rampDays: ib.rampDays },
86	      dailyCap: ib.dailyCap,
87	      healthScore: ib.healthScore,
88	      adaptive: ib.strategy === "ADAPTIVE",
89	      now,
90	    });
91	    const sentToday = await db.coldSend.count({ where: { inboxId: ib.id, sentAt: { gte: dayStart } } });
92	    pool.push({
93	      sendingDomainId: ib.sendingDomainId,
94	      smtp: { host: ib.smtpHost, port: ib.smtpPort, user: ib.smtpUser, passEnc: ib.smtpPassEnc, tls: ib.smtpTls },
95	      candidate: {
96	        id: ib.id,
97	        status: ib.status as RotationInbox["status"],
98	        allowedToday,
99	        sentToday,
100	        authGreen,
101	        lastSendAt: ib.lastSendAt,
102	        minGapSeconds: ib.minGapSeconds,
103	      },
104	      // Send AS the inbox address, keeping the brand's name/postal/reply-to. This is
105	      // what makes rotation real — each message goes out from a different mailbox.
106	      identity: {
107	        ...brand,
108	        fromEmail: ib.email,
109	        sendingDomain: d ? `${d.subdomain ? d.subdomain + "." : ""}${d.domain}` : brand.sendingDomain,
110	      },
111	    });
112	  }
113	  return pool;
114	}
