116	/** Append a deliverability event (the analytics spine). Never throws to the caller. */
117	async function recordDeliverability(
118	  type: "SENT" | "FAILED" | "DELIVERED",
119	  ctx: { inboxId?: string | null; sendingDomainId?: string | null; campaignId: string; contactId?: string | null; sendId: string; meta?: string },
120	): Promise<void> {
121	  const t = type === "FAILED" ? "DEFERRED" : type; // FAILED maps to a soft/deferred signal
122	  try {
123	    await db.deliverabilityEvent.create({
124	      data: {
125	        type: t,
126	        inboxId: ctx.inboxId ?? null,
127	        sendingDomainId: ctx.sendingDomainId ?? null,
128	        campaignId: ctx.campaignId,
129	        contactId: ctx.contactId ?? null,
130	        sendId: ctx.sendId,
131	        meta: (ctx.meta ?? "").slice(0, 300),
132	      },
133	    });
134	  } catch {
135	    /* table not migrated / best-effort — analytics must never fail a send */
136	  }
137	}
138	
139	/** Upper bound on sends per sweep — keeps each worker tick light + jitter sane. */
140	const MAX_SENDS_PER_SWEEP = 50;
141	/** Throttle window (ms) between real sends — jittered to look human, not blasty. */
142	const THROTTLE_MIN_MS = 800;
143	const THROTTLE_MAX_MS = 2600;
144	
145	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
146	const jitter = () => THROTTLE_MIN_MS + Math.floor(Math.random() * (THROTTLE_MAX_MS - THROTTLE_MIN_MS));
147	
148	function appHost(): string | null {
149	  try {
150	    return process.env.APP_URL ? new URL(process.env.APP_URL).host : null;
151	  } catch {
152	    return null;
153	  }
154	}
155	
156	function startOfUtcDay(now = new Date()): Date {
157	  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
158	}
159	
160	/** Current minute-of-day in a timezone (falls back to UTC on a bad tz). */
161	function minutesInTz(now: Date, tz: string): number {
162	  try {
163	    const parts = new Intl.DateTimeFormat("en-US", {
164	      timeZone: tz || "UTC",
165	      hour: "2-digit",
166	      minute: "2-digit",
167	      hour12: false,
168	    }).formatToParts(now);
169	    const h = Number(parts.find((p) => p.type === "hour")?.value ?? "0") % 24;
170	    const m = Number(parts.find((p) => p.type === "minute")?.value ?? "0");
171	    return h * 60 + m;
172	  } catch {
173	    return now.getUTCHours() * 60 + now.getUTCMinutes();
174	  }
175	}
176	
177	function withinSendWindow(
178	  c: { sendWindowStart: number | null; sendWindowEnd: number | null; timezone: string },
179	  now: Date,
180	): boolean {
181	  if (c.sendWindowStart == null || c.sendWindowEnd == null) return true;
182	  const cur = minutesInTz(now, c.timezone || "UTC");
183	  const s = c.sendWindowStart;
184	  const e = c.sendWindowEnd;
185	  return s <= e ? cur >= s && cur < e : cur >= s || cur < e; // handle wrap past midnight
186	}
