188	type CampaignForSend = {
189	  id: string;
190	  brandId: string;
191	  listId: string;
192	  launchedAt: Date | null;
193	  sendWindowStart: number | null;
194	  sendWindowEnd: number | null;
195	  timezone: string;
196	};
