198	/**
199	 * Ensure a ColdSend row exists for every (contact, step) in a campaign, with the
200	 * scheduledFor honouring cumulative step delays from the launch anchor. Idempotent
201	 * — the unique(campaignId, contactId, stepId) + skipDuplicates makes re-runs free.
202	 */
203	async function scheduleCampaignSends(campaign: CampaignForSend): Promise<void> {
204	  const steps = await db.sequenceStep.findMany({
205	    where: { campaignId: campaign.id },
206	    orderBy: { stepOrder: "asc" },
207	    select: { id: true, delayDays: true },
208	  });
209	  if (steps.length === 0) return;
210	
211	  const base = campaign.launchedAt ?? new Date();
212	  // Cumulative offset (days) at each step.
213	  let cumulative = 0;
214	  const stepSchedule = steps.map((s) => {
215	    cumulative += Math.max(0, s.delayDays);
216	    return { stepId: s.id, scheduledFor: new Date(base.getTime() + cumulative * 86_400_000) };
217	  });
218	
219	  const members = await db.emailListMember.findMany({
220	    where: { listId: campaign.listId },
221	    select: { contactId: true, contact: { select: { email: true, emailStatus: true } } },
222	  });
223	  if (members.length === 0) return;
224	
225	  // LEAD-DB exclusion: never schedule a send for a non-mailable (dead / hard-bounced
226	  // / complained / unsubscribed) or globally/brand-suppressed contact. The send-time
227	  // suppression re-check remains as defence-in-depth for rows queued earlier.
228	  const suppressions: SuppressionLike[] = await db.suppression.findMany({
229	    where: { OR: [{ scope: "GLOBAL" }, { scope: "BRAND", brandId: campaign.brandId }] },
230	    select: { email: true, domain: true, scope: true, brandId: true },
231	  });
232	
233	  const rows: { campaignId: string; contactId: string; stepId: string; scheduledFor: Date }[] = [];
234	  for (const m of members) {
235	    if (!isMailableStatus(m.contact?.emailStatus)) continue;
236	    if (m.contact?.email && isSuppressed(m.contact.email, campaign.brandId, suppressions)) continue;
237	    for (const s of stepSchedule) {
238	      rows.push({ campaignId: campaign.id, contactId: m.contactId, stepId: s.stepId, scheduledFor: s.scheduledFor });
239	    }
240	  }
241	  if (rows.length === 0) return;
242	  // createMany + skipDuplicates: never double-queues a message across sweeps.
243	  await db.coldSend.createMany({ data: rows, skipDuplicates: true });
244	}
