246	/**
247	 * Process due sends for one eligible campaign. Returns the number actually sent so
248	 * the caller can respect the per-sweep budget across campaigns.
249	 */
250	async function processDueSends(
251	  campaign: CampaignForSend,
252	  identity: SendIdentity,
253	  ctx: {
254	    now: Date;
255	    transport: MailTransport;
256	    ceiling: number;
257	    warmupEnabled: boolean;
258	    footerDisclosure: string;
259	    budget: number;
260	  },
261	): Promise<number> {
262	  if (ctx.budget <= 0) return 0;
263	  if (!withinSendWindow(campaign, ctx.now)) return 0;
264	
265	  // ===== Phase 3 — rotation pool =====
266	  // If the brand has ACTIVE inboxes, distribute sends across them honouring each
267	  // inbox's warmup limit + dailyCap + min gap (rotation.selectNextInbox). Otherwise
268	  // fall back to the Phase 2 brand-level warmup cap (unchanged).
269	  const pool = await loadBrandRotationPool(campaign.brandId, identity, ctx.now);
270	  const useRotation = pool.length > 0;
271	  const poolById = new Map(pool.map((p) => [p.candidate.id, p]));
272	
273	  // Per-inbox daily cap (warmup-aware). Counts REAL sends today for the brand.
274	  const brand = await db.brand.findUnique({
275	    where: { id: campaign.brandId },
276	    select: { warmupStartedAt: true, dailySendCap: true },
277	  });
278	  const cap = effectiveDailyCap({
279	    warmupStartedAt: brand?.warmupStartedAt ?? null,
280	    ceiling: brand?.dailySendCap ?? ctx.ceiling,
281	    warmupEnabled: ctx.warmupEnabled,
282	    now: ctx.now,
283	  });
284	  let sentToday = await db.coldSend.count({
285	    where: { campaign: { brandId: campaign.brandId }, sentAt: { gte: startOfUtcDay(ctx.now) } },
286	  });
287	  if (!useRotation && sentToday >= cap) return 0;
288	
289	  // Suppression rows for this brand, loaded once (GLOBAL + this brand's BRAND tier).
290	  const suppressions: SuppressionLike[] = await db.suppression.findMany({
291	    where: { OR: [{ scope: "GLOBAL" }, { scope: "BRAND", brandId: campaign.brandId }] },
292	    select: { email: true, domain: true, scope: true, brandId: true },
293	  });
294	
295	  const due = await db.coldSend.findMany({
296	    where: {
297	      campaignId: campaign.id,
298	      status: "QUEUED",
299	      stepId: { not: null },
300	      scheduledFor: { lte: ctx.now },
301	    },
302	    orderBy: { scheduledFor: "asc" },
303	    take: ctx.budget,
304	    include: {
305	      contact: {
306	        select: {
307	          id: true,
308	          email: true,
309	          fullName: true,
310	          title: true,
311	          firstEmailedAt: true,
312	          emailStatus: true,
313	          business: { select: { name: true } },
314	        },
315	      },
316	      step: { select: { subject: true, bodyMarkdown: true } },
317	    },
318	  });
319	
320	  let sent = 0;
321	  for (const s of due) {
322	    if (!s.step || !s.contact) continue;
323	
324	    // GUARDRAIL #4 — re-check suppression immediately before the send.
325	    if (isSuppressed(s.contact.email, campaign.brandId, suppressions)) {
326	      await db.coldSend.update({ where: { id: s.id }, data: { status: "SUPPRESSED" } });
327	      continue;
328	    }
329	
330	    // GUARDRAIL #5 — re-check mailability immediately before the send. A contact
331	    // can go DEAD (hard bounce, complaint) any time between being scheduled and its
332	    // scheduledFor firing, since steps are scheduled days in advance; scheduling-time
333	    // mailability alone is not enough.
334	    if (!isMailableStatus(s.contact.emailStatus)) {
335	      await db.coldSend.update({ where: { id: s.id }, data: { status: "SUPPRESSED" } });
336	      continue;
337	    }
338	
339	    // Pick the sending inbox (rotation) or fall back to the brand identity + cap.
340	    let chosen: PoolInbox | null = null;
341	    if (useRotation) {
342	      const cand = selectNextInbox(pool.map((p) => p.candidate), ctx.now);
343	      if (!cand) break; // no eligible inbox right now — leave the rest QUEUED
344	      chosen = poolById.get(cand.id) ?? null;
345	      if (!chosen) break;
346	    } else if (sentToday >= cap) {
347	      break; // brand-level cap reached
348	    }
349	
350	    const sendIdentity = chosen ? chosen.identity : identity;
351	    const token = openTrackingToken(s.id);
352	    // Tracking/unsubscribe links must live on the ISOLATED sending domain, not
353	    // the platform's own appUrl() (nxeon.cloud) — buildMessage() defaults to
354	    // appUrl() when no base is given, which put nxeon.cloud in every
355	    // List-Unsubscribe header and click-tracking URL a cold-outreach recipient
356	    // saw, unmasking the "separate" brand entirely. trynxeon.com's own nginx
357	    // redirects any path (preserving it via $request_uri) straight to the real
358	    // app, so this is a real, working link that just shows the isolated
359	    // domain to the recipient instead of the protected one.
360	    const sendDomain = (sendIdentity.fromEmail ?? "").split("@")[1]?.trim();
361	    const linkBase = sendDomain ? `https://${sendDomain}` : undefined;
362	    const msg = buildMessage({
363	      identity: sendIdentity,
364	      step: s.step,
365	      contact: s.contact,
366	      sendId: s.id,
367	      base: linkBase,
368	      footerDisclosure: ctx.footerDisclosure,
369	      track: true,
370	    });
371	
372	    // Send via the CHOSEN INBOX'S OWN relay — never the shared ctx.transport
373	    // (the platform's transactional SMTP), which is only a last-resort fallback
374	    // for the brand-level (no-rotation-pool) path below.
375	    let transport = ctx.transport;
376	    if (chosen) {
377	      const pass = decryptSecret(chosen.smtp.passEnc);
378	      if (!pass) {
379	        await db.coldSend.update({ where: { id: s.id }, data: { status: "FAILED", error: "inbox has no usable SMTP password", trackingToken: token } });
380	        continue;
381	      }
382	      transport = new NxeonSmtpTransport({ host: chosen.smtp.host, port: chosen.smtp.port, user: chosen.smtp.user, pass, secure: chosen.smtp.tls });
383	    }
384	
385	    try {
386	      const res = await transport.send(msg);
387	      const sentAt = new Date();
388	      await db.coldSend.update({
389	        where: { id: s.id },
390	        data: {
391	          status: "SENT",
392	          sentAt,
393	          inboxId: chosen?.candidate.id ?? null,
394	          messageId: res.messageId ?? null,
395	          trackingToken: token,
396	          error: null,
397	        },
398	      });
399	      await db.emailEvent.create({ data: { sendId: s.id, type: "SENT" } });
400	      // LEAD-DB engagement counters: this contact was just emailed.
401	      await db.contact
402	        .update({
403	          where: { id: s.contact.id },
404	          data: {
405	            timesEmailed: { increment: 1 },
406	            lastEmailedAt: sentAt,
407	            lastCampaignId: campaign.id,
408	            ...(s.contact.firstEmailedAt ? {} : { firstEmailedAt: sentAt }),
409	          },
410	        })
411	        .catch(() => null);
412	      await recordDeliverability("SENT", {
413	        inboxId: chosen?.candidate.id ?? null,
414	        sendingDomainId: chosen?.sendingDomainId ?? null,
415	        campaignId: campaign.id,
416	        contactId: s.contact.id,
417	        sendId: s.id,
418	      });
419	      if (chosen) {
420	        // Advance the rotation state so successive picks rotate + honour the gap.
421	        chosen.candidate.sentToday += 1;
422	        chosen.candidate.lastSendAt = sentAt;
423	        await db.inbox.update({ where: { id: chosen.candidate.id }, data: { lastSendAt: sentAt } }).catch(() => null);
424	      }
425	      sentToday++;
426	      sent++;
427	    } catch (err) {
428	      const error = String((err as Error)?.message ?? err).slice(0, 500);
429	      await db.coldSend.update({ where: { id: s.id }, data: { status: "FAILED", error, inboxId: chosen?.candidate.id ?? null, trackingToken: token } });
430	      await db.emailEvent.create({ data: { sendId: s.id, type: "FAILED", meta: error } });
431	      await recordDeliverability("FAILED", {
432	        inboxId: chosen?.candidate.id ?? null,
433	        sendingDomainId: chosen?.sendingDomainId ?? null,
434	        campaignId: campaign.id,
435	        contactId: s.contact.id,
436	        sendId: s.id,
437	        meta: error,
438	      });
439	      await logEvent("error", "coldemail.send.fail", { campaignId: campaign.id, sendId: s.id, error });
440	    }
441	
442	    await sleep(jitter());
443	  }
444	  return sent;
445	}
