447	/** Mark a campaign DONE once nothing is left QUEUED (all sends terminal). */
448	async function maybeCompleteCampaign(campaignId: string): Promise<void> {
449	  const remaining = await db.coldSend.count({ where: { campaignId, status: "QUEUED" } });
450	  if (remaining > 0) return;
451	  const any = await db.coldSend.count({ where: { campaignId } });
452	  if (any === 0) return; // nothing was ever scheduled — leave it SENDING
453	  await db.coldCampaign.update({ where: { id: campaignId }, data: { status: "DONE" } });
454	}
