456	/**
457	 * The send sweep. GATED by `cold_email_sending_enabled` — the single line that
458	 * keeps everything below inert until a human enables sending on prod.
459	 */
460	export async function coldEmailSendSweep(): Promise<void> {
461	  // ===== GUARDRAIL #1 — MASTER KILL-SWITCH =====
462	  if (!(await getSettingBool("cold_email_sending_enabled", false))) return;
463	
464	  let campaigns: CampaignForSend[];
465	  try {
466	    campaigns = await db.coldCampaign.findMany({
467	      where: { status: "SENDING" },
468	      select: {
469	        id: true,
470	        brandId: true,
471	        listId: true,
472	        launchedAt: true,
473	        sendWindowStart: true,
474	        sendWindowEnd: true,
475	        timezone: true,
476	      },
477	    });
478	  } catch {
479	    // Table not migrated on this environment yet — no-op (mirrors marketing sweep).
480	    return;
481	  }
482	  if (campaigns.length === 0) return;
483	
484	  const protectedSet = protectedDomainSet(await getSetting("cold_email_protected_domains"), appHost());
485	  const ceiling = getSettingIntSafe(await getSetting("coldemail_warmup_ceiling"), 40);
486	  const warmupEnabled = (await getSetting("coldemail_warmup_enabled")) !== "false";
487	  const footerDisclosure = await getSetting("coldemail_footer_disclosure");
488	  const now = new Date();
489	
490	  let transport: MailTransport;
491	  try {
492	    transport = await getTransport("nxeon-smtp");
493	  } catch (err) {
494	    await logEvent("error", "coldemail.transport.init", { message: String(err) });
495	    return;
496	  }
497	
498	  let budget = MAX_SENDS_PER_SWEEP;
499	  for (const campaign of campaigns) {
500	    if (budget <= 0) break;
501	
502	    const brand = await db.brand.findUnique({ where: { id: campaign.brandId } });
503	    if (!brand) continue;
504	
505	    // ===== GUARDRAILS #2 + #3 — reputation isolation + per-brand gate =====
506	    const eligibility = evaluateSendEligibility(brand, protectedSet);
507	    if (!eligibility.eligible) {
508	      await logEvent("warn", "coldemail.send.brand_blocked", {
509	        campaignId: campaign.id,
510	        brandId: brand.id,
511	        reasons: eligibility.reasons,
512	      });
513	      continue;
514	    }
515	
516	    const identity: SendIdentity = {
517	      id: brand.id,
518	      name: brand.name,
519	      fromName: brand.fromName,
520	      fromEmail: brand.fromEmail,
521	      replyTo: brand.replyTo,
522	      sendingDomain: brand.sendingDomain,
523	      physicalPostalAddress: brand.physicalPostalAddress,
524	    };
525	
526	    try {
527	      await scheduleCampaignSends(campaign);
528	      const sent = await processDueSends(campaign, identity, {
529	        now,
530	        transport,
531	        ceiling,
532	        warmupEnabled,
533	        footerDisclosure,
534	        budget,
535	      });
536	      budget -= sent;
537	      await maybeCompleteCampaign(campaign.id);
538	    } catch (err) {
539	      await logEvent("error", "coldemail.send.campaign", { campaignId: campaign.id, message: String(err) });
540	    }
541	  }
542	}
