110	// ---------------------------------------------------------------------------
111	// CSV parsing (RFC-4180-ish: quoted fields, embedded commas/newlines, "" escape).
112	// ---------------------------------------------------------------------------
113	
114	export function parseCsv(text: string): { headers: string[]; rows: string[][] } {
115	  const records: string[][] = [];
116	  let field = "";
117	  let row: string[] = [];
118	  let inQuotes = false;
119	  const src = (text ?? "").replace(/\r\n?/g, "\n");
120	
121	  for (let i = 0; i < src.length; i++) {
122	    const c = src[i];
123	    if (inQuotes) {
124	      if (c === '"') {
125	        if (src[i + 1] === '"') {
126	          field += '"';
127	          i++;
128	        } else {
129	          inQuotes = false;
130	        }
131	      } else {
132	        field += c;
133	      }
134	    } else if (c === '"') {
135	      inQuotes = true;
136	    } else if (c === ",") {
137	      row.push(field);
138	      field = "";
139	    } else if (c === "\n") {
140	      row.push(field);
141	      records.push(row);
142	      row = [];
143	      field = "";
144	    } else {
145	      field += c;
146	    }
147	  }
148	  if (field.length > 0 || row.length > 0) {
149	    row.push(field);
150	    records.push(row);
151	  }
152	
153	  const nonEmpty = records.filter((r) => r.some((f) => f.trim() !== ""));
154	  if (nonEmpty.length === 0) return { headers: [], rows: [] };
155	  const headers = nonEmpty[0].map((h) => h.trim());
156	  return { headers, rows: nonEmpty.slice(1) };
157	}
158	
159	/** Map a parsed CSV (headers + rows) to canonical LeadRow objects. */
160	export function csvToLeadRows(headers: string[], rows: string[][]): LeadRow[] {
161	  const cols = headers.map((h) => IMPORT_HEADER_ALIASES[h.trim().toLowerCase()] ?? null);
162	  return rows.map((r) => {
163	    const lead: LeadRow = {};
164	    cols.forEach((field, i) => {
165	      if (field) lead[field] = (r[i] ?? "").trim();
166	    });
167	    return lead;
168	  });
169	}
170	
171	// ---------------------------------------------------------------------------
172	// Normalisation + validation of a single lead row
173	// ---------------------------------------------------------------------------
174	
175	// Stricter than a bare "anything@anything.anything" check: the old pattern let
176	// through scraper/URL-decoding artifacts (a literal "%20"/"%e2%80%8b" prefix, a
177	// leading dot) that real addresses never have. The local part must start with an
178	// alphanumeric; each domain label must start and end with an alphanumeric.
179	const EMAIL_RE =
180	  /^[a-zA-Z0-9][a-zA-Z0-9._+-]*@[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?)+$/;
181	
182	export type NormalizedLead = {
183	  email: string;
184	  domain: string;
185	  fullName: string;
186	  title: string;
187	  business: {
188	    name: string;
189	    category: string;
190	    businessType: string;
191	    website: string;
192	    phone: string;
193	    addressLine: string;
194	    city: string;
195	    region: string;
196	    country: string;
197	    companySize: string;
198	  };
199	  sourceUrl: string;
200	};
201	
202	/**
203	 * Normalise + validate a row. Returns null when there is no usable email — the lead
204	 * database is keyed on emailable people, so an email-less row can't be a lead. The
205	 * business name falls back to the email domain so a name-less row still imports.
206	 */
207	export function normalizeLeadRow(raw: LeadRow): NormalizedLead | null {
208	  const email = normalizeEmail(raw.email);
209	  if (!email || !EMAIL_RE.test(email)) return null;
210	  const domain = emailDomain(email);
211	  const website = (raw.website ?? "").trim();
212	  const name = (raw.name ?? "").trim() || domain;
213	  return {
214	    email,
215	    domain,
216	    fullName: (raw.fullName ?? "").trim().slice(0, 160),
217	    title: (raw.title ?? "").trim().slice(0, 120),
218	    business: {
219	      name: name.slice(0, 160),
220	      category: (raw.category ?? "").trim().slice(0, 120),
221	      businessType: (raw.businessType ?? "").trim().slice(0, 120),
222	      website: website ? normalizeDomain(website).slice(0, 200) || website.slice(0, 200) : "",
223	      phone: (raw.phone ?? "").trim().slice(0, 60),
224	      addressLine: (raw.addressLine ?? "").trim().slice(0, 200),
225	      city: (raw.city ?? "").trim().slice(0, 120),
226	      region: (raw.region ?? "").trim().slice(0, 120),
227	      country: (raw.country ?? "").trim().slice(0, 120),
228	      companySize: (raw.companySize ?? "").trim().slice(0, 60),
229	    },
230	    sourceUrl: (raw.sourceUrl ?? "").trim().slice(0, 300),
231	  };
232	}
