1	// Cold Email Engine — sending transport + message rendering (Phase 2).
2	//
3	// This module has TWO halves:
4	//
5	//   1. PURE rendering (`renderStepBody`, `buildMessage`, `injectTracking`,
6	//      markdown → HTML). No I/O, no DB, no network — the send worker AND the test
7	//      suite call these identically. Importing this module never opens a socket.
8	//
9	//   2. A pluggable `MailTransport` interface with a Nxeon Mail SMTP adapter
10	//      (reusing the platform's SMTP Setting mechanism from lib/mailer.ts) and an
11	//      SES adapter SEAM for later. Only `NxeonSmtpTransport.send()` touches the
12	//      network, and it is only ever reached from the send worker, which is hard-
13	//      gated behind the `cold_email_sending_enabled` kill-switch.
14	//
15	// SAFETY: nothing here checks the kill-switch or the suppression list itself —
16	// those gates live in the worker so they are enforced once, at the choke point,
17	// immediately before each send. This module assumes the caller has already
18	// cleared a message to send.
19	
20	import nodemailer from "nodemailer";
21	import { appUrl } from "@/lib/email-render";
22	import {
23	  complianceFooter,
24	  unsubscribeToken,
25	  openTrackingToken,
26	  clickTrackingToken,
27	  normalizeDomain,
28	  type BrandLike,
29	} from "@/lib/coldemail/compliance";
30	
31	// ---------------------------------------------------------------------------
32	// Shapes
33	// ---------------------------------------------------------------------------
34	
35	export type SendIdentity = BrandLike & {
36	  id: string;
37	  name?: string | null;
38	  fromName?: string | null;
39	  fromEmail?: string | null;
40	  replyTo?: string | null;
41	  sendingDomain?: string | null;
42	};
43	
44	export type StepLike = { subject: string; bodyMarkdown: string };
45	
46	export type ContactLike = {
47	  id: string;
48	  email: string;
49	  fullName?: string | null;
50	  title?: string | null;
51	  business?: { name?: string | null } | null;
52	};
53	
54	export type RenderedMessage = {
55	  from: string;
56	  to: string;
57	  replyTo?: string;
58	  subject: string;
59	  html: string;
60	  text: string;
61	  headers: Record<string, string>;
62	};
63	
64	export type SendResult = { messageId?: string };
65	
66	/** A transport is anything that can put one fully-rendered message on the wire. */
67	export interface MailTransport {
68	  readonly name: string;
69	  send(msg: RenderedMessage): Promise<SendResult>;
70	}
71	
72	// ---------------------------------------------------------------------------
73	// Minimal, dependency-free markdown → HTML (no `marked` in this repo).
74	// Supports: paragraphs, line breaks, **bold**, *italic*, [text](url), and bare
75	// autolinks. Everything is escaped first, so raw HTML in the body is inert.
76	// ---------------------------------------------------------------------------
77	
78	function esc(s: string): string {
79	  return s
80	    .replace(/&/g, "&amp;")
81	    .replace(/</g, "&lt;")
82	    .replace(/>/g, "&gt;")
83	    .replace(/"/g, "&quot;");
84	}
85	
86	/** Render a markdown body to safe inline-styled HTML paragraphs. */
87	export function markdownToHtml(md: string): string {
88	  const inline = (raw: string): string => {
89	    let s = esc(raw);
90	    // [label](http…) links — label and URL are already escaped.
91	    s = s.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, (_m, label, url) => {
92	      return `<a href="${url}" style="color:#6f47f5;text-decoration:underline;">${label}</a>`;
93	    });
94	    // Bare autolinks not already inside an <a href="…">.
95	    s = s.replace(/(^|[\s(])((https?:\/\/[^\s<)]+))/g, (_m, pre, url) => {
96	      return `${pre}<a href="${url}" style="color:#6f47f5;text-decoration:underline;">${url}</a>`;
97	    });
98	    s = s.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
99	    s = s.replace(/(^|[^*])\*([^*]+)\*/g, "$1<em>$2</em>");
100	    return s;
101	  };
102	
103	  const paragraphs = String(md ?? "")
104	    .replace(/\r\n?/g, "\n")
105	    .split(/\n{2,}/)
106	    .map((p) => p.trim())
107	    .filter(Boolean)
108	    .map((p) => {
109	      const body = p.split("\n").map(inline).join("<br/>");
110	      return `<p style="margin:0 0 16px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.65;color:#4a4763;">${body}</p>`;
111	    });
112	  return paragraphs.join("\n");
113	}
114	
115	// ---------------------------------------------------------------------------
116	// Variable substitution for personalization tokens ({{firstName}}, {{company}}…)
117	// ---------------------------------------------------------------------------
118	
119	export function contactVars(contact: ContactLike): Record<string, string> {
120	  const full = (contact.fullName ?? "").trim();
121	  const firstName = full.split(/\s+/)[0] ?? "";
122	  return {
123	    firstName,
124	    fullName: full,
125	    title: (contact.title ?? "").trim(),
126	    email: contact.email,
127	    company: (contact.business?.name ?? "").trim(),
128	  };
129	}
130	
131	function substitute(input: string, vars: Record<string, string>): string {
132	  return String(input ?? "").replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_m, key: string) =>
133	    vars[key] !== undefined ? vars[key] : "",
134	  );
135	}
136	
137	// ---------------------------------------------------------------------------
138	// Tracking injection (open pixel + click-through rewriting). PURE.
139	// ---------------------------------------------------------------------------
140	
141	export function openPixelUrl(base: string, sendId: string): string {
142	  return `${base.replace(/\/$/, "")}/api/coldemail/track/open/${openTrackingToken(sendId)}`;
143	}
144	
145	export function clickWrapUrl(base: string, sendId: string, target: string): string {
146	  return `${base.replace(/\/$/, "")}/api/coldemail/track/click/${clickTrackingToken(sendId, target)}`;
147	}
148	
149	/**
150	 * Rewrite outbound `<a href="http…">` links through the click-tracking redirect
151	 * and append a 1x1 open pixel. Applied ONLY at send time — previews never call
152	 * this, so an operator's preview shows real, unwrapped links. The unsubscribe
153	 * link is deliberately left un-wrapped: it must remain a direct, one-click,
154	 * no-JS, no-redirect target per RFC 8058.
155	 */
156	export function injectTracking(html: string, sendId: string, base: string, opts: { skip?: (url: string) => boolean } = {}): string {
157	  const skip = opts.skip ?? (() => false);
158	  const rewritten = html.replace(/href="(https?:\/\/[^"]+)"/gi, (m, url: string) => {
159	    if (skip(url)) return m;
160	    return `href="${clickWrapUrl(base, sendId, url)}"`;
161	  });
162	  const pixel = `<img src="${openPixelUrl(base, sendId)}" width="1" height="1" alt="" style="display:none;width:1px;height:1px;border:0;" />`;
163	  return `${rewritten}\n${pixel}`;
164	}
165	
166	// ---------------------------------------------------------------------------
167	// Message rendering (PURE — the heart the tests exercise)
168	// ---------------------------------------------------------------------------
169	
170	/** Build the `From` header value from a brand identity. */
171	export function fromHeader(identity: SendIdentity): string {
172	  const email = (identity.fromEmail ?? "").trim();
173	  const name = (identity.fromName ?? identity.name ?? "").trim();
174	  return name ? `${name} <${email}>` : email;
175	}
176	
177	/** The From domain used for reputation-isolation checks. */
178	export function identityDomain(identity: SendIdentity): string {
179	  return normalizeDomain(identity.sendingDomain) || normalizeDomain(identity.fromEmail);
180	}
181	
182	export type BuildMessageOpts = {
183	  identity: SendIdentity;
184	  step: StepLike;
185	  contact: ContactLike;
186	  /** ColdSend id — anchors tracking tokens. Omit for a plain preview. */
187	  sendId?: string;
188	  /** Base URL for links (defaults to appUrl()). */
189	  base?: string;
190	  /** Extra disclosure line appended under the required footer. */
191	  footerDisclosure?: string;
192	  /** Inject open pixel + click tracking. FALSE for previews. */
193	  track?: boolean;
194	};
195	
196	/**
197	 * Render one SequenceStep into a fully-formed, compliant message:
198	 *  - subject + markdown body with {{tokens}} substituted,
199	 *  - the mandatory compliance footer (postal address + one-click unsubscribe),
200	 *  - `List-Unsubscribe` + `List-Unsubscribe-Post` headers (RFC 8058),
201	 *  - open/click tracking when `track` and a `sendId` are supplied.
202	 *
203	 * No network, no DB — deterministic given its inputs.
204	 */
205	/**
206	 * Minimal HTML shell for a cold-email send — deliberately NOT `wrapEmail()`
207	 * (the transactional shell used for invoices/password-resets/etc). That shell
208	 * hardcodes its own footer with a fixed company address and "you're receiving
209	 * this because you have a Nxeon account" — both wrong here: `buildMessage`
210	 * already renders the correct, per-brand compliance footer (real postal
211	 * address + real unsubscribe) right in `contentHtml`, so wrapping it in a
212	 * second template just duplicated that footer with WRONG information
213	 * underneath the right one. Confirmed live: a rendered preview showed two
214	 * different postal addresses in the same email and a false account-holder
215	 * claim to a cold-outreach recipient who has never signed up for anything.
216	 *
217	 * Also deliberately plain rather than branded: no gradient header, no logo
218	 * image, no Dashboard/Help/Support nav — a heavy marketing-template look is
219	 * exactly what current cold-email deliverability guidance says to avoid; a
220	 * cold email should read like a real person's message, not a mass send.
221	 */
222	function wrapColdEmailHtml(contentHtml: string, preheader: string): string {
223	  const hidden = `<div style="display:none;max-height:0;overflow:hidden;mso-hide:all;font-size:1px;line-height:1px;color:#ffffff;opacity:0;">${esc(preheader)}</div>`;
224	  return `<!doctype html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><meta name="color-scheme" content="light"/><title></title></head>
225	<body style="margin:0;padding:0;background-color:#ffffff;-webkit-text-size-adjust:100%;">
226	${hidden}
227	<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td align="center" style="padding:24px 16px;">
228	<table role="presentation" width="560" cellpadding="0" cellspacing="0" border="0" style="width:560px;max-width:100%;">
229	<tr><td style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
230	${contentHtml}
231	</td></tr>
232	</table>
233	</td></tr></table>
234	</body></html>`;
235	}
236	
237	export function buildMessage(opts: BuildMessageOpts): RenderedMessage {
238	  const { identity, step, contact } = opts;
239	  const base = (opts.base ?? appUrl()).replace(/\/$/, "");
240	  const vars = contactVars(contact);
241	
242	  const subject = substitute(step.subject, vars);
243	
244	  // Unsubscribe target (RFC 8058 one-click). Same HMAC token the endpoint verifies.
245	  const unsubToken = unsubscribeToken(contact.id, identity.id);
246	  const unsubscribeUrl = `${base}/api/coldemail/unsubscribe?token=${unsubToken}`;
247	
248	  // Body: markdown → HTML, then the mandatory footer as an HTML block.
249	  const bodyHtml = markdownToHtml(substitute(step.bodyMarkdown, vars));
250	  const footerText = complianceFooter(identity, unsubscribeUrl);
251	  const disclosure = (opts.footerDisclosure ?? "").trim();
252	  const footerHtml = renderFooterHtml(identity, unsubscribeUrl, disclosure);
253	
254	  let contentHtml = `${bodyHtml}\n${footerHtml}`;
255	  if (opts.track && opts.sendId) {
256	    contentHtml = injectTracking(contentHtml, opts.sendId, base, {
257	      // Never route the unsubscribe link through click-tracking.
258	      skip: (url) => url.includes("/api/coldemail/unsubscribe"),
259	    });
260	  }
261	
262	  const html = wrapColdEmailHtml(contentHtml, subject);
263	  const text = buildPlainText(substitute(step.bodyMarkdown, vars), footerText);
264	
265	  const headers: Record<string, string> = {
266	    // RFC 8058: HTTPS one-click unsubscribe. The POST target and the GET are the
267	    // same URL; the endpoint honours the POST immediately.
268	    "List-Unsubscribe": `<${unsubscribeUrl}>`,
269	    "List-Unsubscribe-Post": "List-Unsubscribe=One-Click",
270	    // Bulk-sender hygiene — a stable, honest precedence marker.
271	    "X-Nxeon-Cold-Email": "1",
272	  };
273	
274	  return {
275	    from: fromHeader(identity),
276	    to: contact.email,
277	    replyTo: (identity.replyTo ?? "").trim() || undefined,
278	    subject,
279	    html,
280	    text,
281	    headers,
282	  };
283	}
284	
285	/** The compliance footer, styled as an HTML block for the email body. */
286	function renderFooterHtml(identity: SendIdentity, unsubscribeUrl: string, disclosure: string): string {
287	  const address = (identity.physicalPostalAddress ?? "").trim() || "[physical postal address not set]";
288	  const parts = [
289	    disclosure ? esc(disclosure) : "You are receiving this message as a business contact.",
290	    `Our postal address: ${esc(address)}`,
291	    `To stop receiving these emails, <a href="${unsubscribeUrl}" style="color:#8a86a3;text-decoration:underline;">unsubscribe here</a>.`,
292	  ];
293	  return `<div style="margin-top:28px;padding-top:16px;border-top:1px solid #ecebf3;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:12px;line-height:1.6;color:#8a86a3;">${parts.join("<br/>")}</div>`;
294	}
295	
296	/** Plain-text alternative: markdown stripped of decoration + the footer text. */
297	function buildPlainText(bodyMarkdown: string, footerText: string): string {
298	  const body = String(bodyMarkdown ?? "")
299	    .replace(/\r\n?/g, "\n")
300	    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, "$1 ($2)")
301	    .replace(/\*\*([^*]+)\*\*/g, "$1")
302	    .replace(/\*([^*]+)\*/g, "$1")
303	    .trim();
304	  return `${body}\n\n---\n${footerText}\n`;
305	}
