307	// ---------------------------------------------------------------------------
308	// Transports
309	// ---------------------------------------------------------------------------
310	
311	type SmtpConfig = {
312	  host: string;
313	  port: number;
314	  user: string;
315	  pass: string;
316	  secure: boolean;
317	};
318	
319	/**
320	 * Load the platform SMTP settings the same way lib/mailer.ts does — the same
321	 * Setting rows (smtp_host/port/user/pass/secure), the same encrypted-password
322	 * tolerance, the same env fallback. Loaded lazily so importing this module never
323	 * touches the DB (keeps the module unit-testable and side-effect-free).
324	 */
325	async function loadSmtpConfig(): Promise<SmtpConfig> {
326	  const { db } = await import("@/lib/db");
327	  const { decryptSecret } = await import("@/lib/crypto-box");
328	  const rows = await db.setting.findMany({
329	    where: { key: { in: ["smtp_host", "smtp_port", "smtp_user", "smtp_pass", "smtp_secure"] } },
330	  });
331	  const s = Object.fromEntries(rows.map((r) => [r.key, r.value])) as Record<string, string>;
332	  const storedPass = s.smtp_pass;
333	  const pass = storedPass ? decryptSecret(storedPass) ?? storedPass : process.env.SMTP_PASS || "";
334	  return {
335	    host: s.smtp_host || process.env.SMTP_HOST || "",
336	    port: Number(s.smtp_port || process.env.SMTP_PORT || 587),
337	    user: s.smtp_user || process.env.SMTP_USER || "",
338	    pass,
339	    secure: (s.smtp_secure ?? process.env.SMTP_SECURE) === "true",
340	  };
341	}
342	
343	/**
344	 * Nxeon Mail (Mailcow) SMTP transport. The From identity is per-brand (passed on
345	 * each message) rather than the platform's transactional `smtp_from`, so a cold
346	 * campaign always sends as its dedicated sending identity — never as the platform.
347	 */
348	export class NxeonSmtpTransport implements MailTransport {
349	  readonly name = "nxeon-smtp";
350	  constructor(private readonly cfg: SmtpConfig) {}
351	
352	  private transporter() {
353	    if (!this.cfg.host) {
354	      return nodemailer.createTransport({ sendmail: true, newline: "unix", path: "/usr/sbin/sendmail" });
355	    }
356	    const servername = process.env.SMTP_TLS_SERVERNAME || undefined;
357	    return nodemailer.createTransport({
358	      host: this.cfg.host,
359	      port: this.cfg.port,
360	      secure: this.cfg.secure,
361	      auth: this.cfg.user ? { user: this.cfg.user, pass: this.cfg.pass } : undefined,
362	      ...(servername ? { tls: { servername } } : {}),
363	    });
364	  }
365	
366	  async send(msg: RenderedMessage): Promise<SendResult> {
367	    const info = await this.transporter().sendMail({
368	      from: msg.from,
369	      to: msg.to,
370	      replyTo: msg.replyTo,
371	      subject: msg.subject,
372	      html: msg.html,
373	      text: msg.text,
374	      headers: msg.headers,
375	    });
376	    return { messageId: (info as { messageId?: string })?.messageId };
377	  }
378	}
379	
380	/**
381	 * Amazon SES adapter SEAM. Left as a stub because SES is not provisioned yet and
382	 * this phase must not add dependencies or send anything. When a brand's domain
383	 * lives on SES, wire the AWS SDK here behind the same interface — the worker code
384	 * does not change.
385	 */
386	export class SesTransport implements MailTransport {
387	  readonly name = "ses";
388	  async send(_msg: RenderedMessage): Promise<SendResult> {
389	    throw new Error(
390	      "SES transport is not configured. The cold-email engine currently sends only via Nxeon Mail (SMTP). " +
391	        "Provision SES + wire the AWS SDK into SesTransport.send before selecting it.",
392	    );
393	  }
394	}
395	
396	export type TransportKind = "nxeon-smtp" | "ses";
397	
398	/**
399	 * Resolve the transport for a send. Defaults to Nxeon Mail SMTP. Async because
400	 * building the SMTP transport reads the Setting rows; kept off the module's import
401	 * path so tests can import the pure renderers without a DB.
402	 */
403	export async function getTransport(kind: TransportKind = "nxeon-smtp"): Promise<MailTransport> {
404	  if (kind === "ses") return new SesTransport();
405	  return new NxeonSmtpTransport(await loadSmtpConfig());
406	}
