// Cold Email Engine — reply classification (Overhaul Phase 1).
//
// Two layers, both here:
//   1. PURE rule-based detection (no I/O) — catches unsubscribe / opt-out phrasing,
//      out-of-office, and automated bounces/auto-replies. Runs ALWAYS, so an
//      unsubscribe is honoured even with no Anthropic key configured. The tests
//      exercise this + the class→status/stage mapping directly.
//   2. An OPTIONAL AI refinement (askClaude) into interested / not-interested. It
//      only ever UPGRADES a reply the rules left ambiguous; it can never override a
//      rule-detected unsubscribe. Degrades gracefully to null with no API key.
//
// The five buckets mirror the ConversationStatus reply values.

import { askClaude, effectiveKeyFor, type ClaudeMessage } from "@/lib/anthropic";

export type ReplyClass = "INTERESTED" | "NOT_INTERESTED" | "AUTO_REPLY" | "OUT_OF_OFFICE" | "UNSUBSCRIBE";

// Prisma enum string unions (kept as literals so this module stays free of the
// generated client — it must be importable in a DB-less test).
export type ConversationStatusValue =
  | "OPEN"
  | "REPLIED"
  | "INTERESTED"
  | "NOT_INTERESTED"
  | "AUTO_REPLY"
  | "OUT_OF_OFFICE"
  | "UNSUBSCRIBE"
  | "CLOSED";

export type ContactStageValue =
  | "NEW"
  | "CONTACTED"
  | "REPLIED"
  | "INTERESTED"
  | "MEETING_BOOKED"
  | "WON"
  | "LOST";

// ---------------------------------------------------------------------------
// PURE rule-based detection
// ---------------------------------------------------------------------------

const UNSUB_PATTERNS: RegExp[] = [
  /\bunsubscribe\b/i,
  /\bopt[\s-]?out\b/i,
  /\bremove me\b/i,
  /\btake me off\b/i,
  /\bstop (?:emailing|contacting|messaging) me\b/i,
  /\bdo not (?:contact|email|reach out)\b/i,
  /\bdon'?t (?:contact|email) me\b/i,
  /\bno longer (?:wish|want) to (?:receive|hear)\b/i,
];

const OOO_PATTERNS: RegExp[] = [
  /\bout of (?:the )?office\b/i,
  /\bon (?:vacation|holiday|annual leave|parental leave|maternity leave)\b/i,
  /\baway from my (?:desk|email)\b/i,
  /\bwill be (?:back|returning) on\b/i,
  /\blimited access to (?:my )?email\b/i,
];

const AUTO_PATTERNS: RegExp[] = [
  /\bauto(?:matic|mated)?[\s-]?reply\b/i,
  /\bthis is an automated\b/i,
  /\bdo[\s-]?not[\s-]?reply\b/i,
  /\bno[\s-]?reply@\b/i,
  /\bdelivery (?:status notification|has failed)\b/i,
  /\bundeliverable\b/i,
  /\bmailer-daemon\b/i,
  /\baddress not found\b/i,
];

const NOT_INTERESTED_PATTERNS: RegExp[] = [
  /\bnot interested\b/i,
  /\bno thanks?\b/i,
  /\bnot (?:a )?(?:good )?(?:fit|match)\b/i,
  /\bwe(?:'re| are) (?:all )?(?:set|good)\b/i,
  /\balready (?:have|using|work with)\b/i,
  /\bplease stop\b/i,
];

const INTERESTED_PATTERNS: RegExp[] = [
  /\b(?:interested|keen|curious)\b/i,
  /\btell me more\b/i,
  /\b(?:sounds|looks) (?:good|great|interesting)\b/i,
  /\b(?:book|schedule|set up|arrange) (?:a )?(?:call|meeting|demo|time)\b/i,
  /\bhappy to (?:chat|talk|connect)\b/i,
  /\bwhat(?:'s| is) (?:the |your )?(?:pricing|price|cost)\b/i,
  /\bhow (?:much|does it work)\b/i,
];

function anyMatch(text: string, patterns: RegExp[]): boolean {
  return patterns.some((re) => re.test(text));
}

/** Is this reply an unsubscribe / opt-out request? Rule-only, never AI-gated. */
export function isUnsubscribeRequest(text: string): boolean {
  return anyMatch(text ?? "", UNSUB_PATTERNS);
}

/**
 * Rule-based first pass over the reply text (subject + body). Returns a definite
 * class when the rules are confident, else null (hand off to the AI layer). Order
 * matters: an unsubscribe phrase wins over everything, then automated messages,
 * then out-of-office, then the softer interested/not-interested cues.
 */
export function ruleClassify(text: string): ReplyClass | null {
  const t = (text ?? "").toLowerCase();
  if (!t.trim()) return null;
  if (anyMatch(t, UNSUB_PATTERNS)) return "UNSUBSCRIBE";
  if (anyMatch(t, AUTO_PATTERNS)) return "AUTO_REPLY";
  if (anyMatch(t, OOO_PATTERNS)) return "OUT_OF_OFFICE";
  if (anyMatch(t, NOT_INTERESTED_PATTERNS)) return "NOT_INTERESTED";
  if (anyMatch(t, INTERESTED_PATTERNS)) return "INTERESTED";
  return null;
}

// ---------------------------------------------------------------------------
// Class → ConversationStatus / ContactStage mapping (PURE)
// ---------------------------------------------------------------------------

/** Map a reply class to the conversation status it sets. */
export function classToConversationStatus(c: ReplyClass): ConversationStatusValue {
  switch (c) {
    case "INTERESTED":
      return "INTERESTED";
    case "NOT_INTERESTED":
      return "NOT_INTERESTED";
    case "AUTO_REPLY":
      return "AUTO_REPLY";
    case "OUT_OF_OFFICE":
      return "OUT_OF_OFFICE";
    case "UNSUBSCRIBE":
      return "UNSUBSCRIBE";
  }
}

/**
 * Map a reply class to the contact stage it advances to, or null to leave the
 * stage at REPLIED (auto-replies / OOO are not a human signal either way). A reply
 * has already moved the contact to REPLIED before this is applied.
 */
export function classToContactStage(c: ReplyClass): ContactStageValue | null {
  switch (c) {
    case "INTERESTED":
      return "INTERESTED";
    case "NOT_INTERESTED":
      return "LOST";
    case "UNSUBSCRIBE":
      return "LOST";
    case "AUTO_REPLY":
    case "OUT_OF_OFFICE":
      return null;
  }
}

/** Does this class require a GLOBAL suppression? (Unsubscribe only.) */
export function classNeedsSuppression(c: ReplyClass): boolean {
  return c === "UNSUBSCRIBE";
}

/** Parse a raw AI answer down to one of the five buckets, or null if unparseable. */
export function parseAiClass(raw: string): ReplyClass | null {
  const u = (raw ?? "").toUpperCase();
  const buckets: ReplyClass[] = ["UNSUBSCRIBE", "OUT_OF_OFFICE", "AUTO_REPLY", "NOT_INTERESTED", "INTERESTED"];
  for (const b of buckets) {
    if (u.includes(b) || u.includes(b.replace(/_/g, " "))) return b;
  }
  return null;
}

const CLASSIFY_SYSTEM = `You classify a single inbound reply to a B2B cold outreach email into EXACTLY ONE bucket. Answer with ONLY the bucket word, nothing else.

Buckets:
- INTERESTED — wants to learn more, book a call/demo, asks about pricing, positive engagement.
- NOT_INTERESTED — declines, not a fit, already sorted, asks to be left alone (but NOT a formal unsubscribe).
- OUT_OF_OFFICE — an automatic away/vacation message.
- AUTO_REPLY — any other automated message (ticket auto-ack, mailer-daemon, no-reply notice).
- UNSUBSCRIBE — explicitly asks to unsubscribe / opt out / be removed / stop all contact.

Reply with one of: INTERESTED, NOT_INTERESTED, OUT_OF_OFFICE, AUTO_REPLY, UNSUBSCRIBE.`;

/**
 * Full classification for a captured reply.
 *
 *  - Rule pass runs first and is authoritative for UNSUBSCRIBE / OOO / AUTO_REPLY.
 *  - If the rules are ambiguous AND an Anthropic key is available, ask Claude to
 *    pick a bucket (used mainly to separate INTERESTED vs NOT_INTERESTED).
 *  - With no key and ambiguous rules, returns null → the caller leaves the
 *    conversation OPEN (honest: we didn't classify it).
 *
 * Never throws — a classification failure must not break reply ingestion.
 */
export async function classifyReply(
  subject: string,
  body: string,
  opts: { anthropicKeyEnc?: string | null } = {},
): Promise<ReplyClass | null> {
  const text = `${subject ?? ""}\n\n${body ?? ""}`.trim();
  const rule = ruleClassify(text);
  // Rules are decisive for the "safety" buckets — never let AI override them.
  if (rule === "UNSUBSCRIBE" || rule === "AUTO_REPLY" || rule === "OUT_OF_OFFICE") return rule;

  const key = effectiveKeyFor(opts);
  if (!key) return rule; // no AI available — trust the (possibly null) rule verdict

  try {
    const messages: ClaudeMessage[] = [
      { role: "user", content: `Subject: ${subject ?? ""}\n\nBody:\n${(body ?? "").slice(0, 4000)}` },
    ];
