import { simpleParser } from "mailparser";

// ---- Copied verbatim from worker/coldemail-inbox.ts (read-only test copy, not importing/editing the real file) ----
function looksLikeBounce(parsed, fromAddr) {
  if (/^(mailer-daemon|postmaster)@/i.test(fromAddr)) return true;
  if (parsed.attachments?.some((a) => /^message\/delivery-status$/i.test(a.contentType))) return true;
  const subject = (parsed.subject ?? "").toLowerCase();
  return /undeliverable|delivery status notification|delivery has failed|returned to sender|failure notice|mail delivery (?:failed|subsystem)/i.test(
    subject,
  );
}

function normalizeEmail(email) {
  return (email ?? "").trim().toLowerCase();
}

function parseDsnBounce(parsed) {
  const dsnPart = parsed.attachments?.find((a) => /^message\/delivery-status$/i.test(a.contentType));
  const text = dsnPart ? dsnPart.content.toString("utf8") : (parsed.text ?? "");

  const recipMatch = text.match(/Final-Recipient:\s*rfc822;\s*<?([^\s>]+)>?/i);
  const email = normalizeEmail(recipMatch?.[1]);
  if (!email || !email.includes("@")) return null;

  const statusMatch = text.match(/Status:\s*(\d)\.\d+\.\d+/i);
  const hard = statusMatch
    ? statusMatch[1] === "5"
    : !/\btry(?:ing)? again\b|\btemporar(?:y|ily)\b|\bmailbox (?:full|over quota)\b/i.test(text);
  return { email, hard };
}
// ---- end copy ----

const postfixHardBounce = `From: Mail Delivery System <mailer-daemon@example-relay.com>
