MIME-Version: 1.0

--CCC
Content-Type: text/plain; charset=UTF-8

** Address not found **

Your message wasn't delivered to nomail@gmail.com because the address
couldn't be found, or is unable to receive mail.

--CCC
Content-Type: message/delivery-status

Reporting-MTA: dns; mx.google.com

Final-Recipient: rfc822; nomail@gmail.com
Action: failed
Status: 5.1.1

--CCC--
`;

// FALSE-POSITIVE CANDIDATE: a genuine reply from a real prospect whose subject
// happens to contain bounce-shaped wording, with NO delivery-status part.
const legitReplyFalsePositive = `From: Real Prospect <ops@logisticsco.com>
To: hello@trynxeon.com
Subject: Re: delivery has failed for our shipment
Content-Type: text/plain; charset=UTF-8

Hey, actually not related to your email but funny timing -- we're dealing with
a delivery has failed situation with our carrier right now. Anyway, yes I'm
interested in learning more about your hosting, can we set up a call this week?

Thanks,
Alex
`;

// Another legit false-positive candidate using "failure notice"
const legitReplyFailureNotice = `From: Real Prospect <it@retailco.com>
To: hello@trynxeon.com
Subject: RE: Failure notice on our end, ignore previous email
Content-Type: text/plain; charset=UTF-8

Sorry for the confusion, please ignore my last message, that was a mistake.
To answer your question: pricing looks reasonable, send over a contract.
`;

async function run(label, raw) {
  const parsed = await simpleParser(raw);
  const fromAddr = normalizeEmail(parsed.from?.value?.[0]?.address ?? "");
  const bounce = looksLikeBounce(parsed, fromAddr);
  console.log(`\n=== ${label} ===`);
  console.log("from:", fromAddr, "| subject:", parsed.subject);
  console.log("looksLikeBounce:", bounce);
  if (bounce) {
    const dsn = parseDsnBounce(parsed);
    console.log("parseDsnBounce result:", dsn);
  }
}

await run("Postfix hard bounce (5.1.1)", postfixHardBounce);
await run("Exchange soft bounce (4.2.2, mailbox full)", exchangeSoftBounce);
await run("Gmail-style hard bounce (5.1.1)", gmailStyleBounce);
await run("FALSE POSITIVE: legit reply, 'delivery has failed' in subject", legitReplyFalsePositive);
await run("FALSE POSITIVE: legit reply, 'failure notice' in subject", legitReplyFailureNotice);

